internal static class S002HistoricalProducerPathControls {
 static void Main(){var m=typeof(SourcePlacementDomain).GetMethod("HistoricalProducerBinary",BindingFlags.Static|BindingFlags.NonPublic);if(m==null)throw new Exception("Missing scope helper");bool Check(string path)=>(bool)m.Invoke(null,new object[]{path,"/tmp/capture"});if(!Check("/tmp/capture/Library/ScriptAssemblies/Game.Editor.dll")||Check("/tmp/capture/Assets/Game.Editor.dll")||Check("/tmp/capture/Library/ScriptAssemblies/sub/Game.Editor.dll")||Check("/tmp/capture/Library/ScriptAssemblies/../other/Game.Editor.dll")||Check("/tmp/capture/Library/ScriptAssemblies/Game.Editor.cs")||Check("/tmp/capture-other/Library/ScriptAssemblies/Game.Editor.dll"))throw new Exception("Producer binary scope changed");
  var dependency=typeof(SourcePlacementDomain).GetMethod("RequireCurrentCapturedDependency",BindingFlags.Static|BindingFlags.NonPublic);string root=Path.Combine("/private/tmp","s002-dependency-"+Guid.NewGuid().ToString("N"));try{foreach(string name in new[]{"Assets/test.asset","Packages/example/source.cs","Library/PackageCache/example@123/asset.mat"}){string full=Path.Combine(root,name);Directory.CreateDirectory(Path.GetDirectoryName(full));File.WriteAllText(full,"original");string hash;using(var h=SHA256.Create())hash=BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(full))).Replace("-","").ToLowerInvariant();var pins=new Dictionary<string,string>();dependency.Invoke(null,new object[]{root,name,hash,pins});if(!pins.ContainsKey(full))throw new Exception("Dependency not retained");File.WriteAllText(full,"changed");try{dependency.Invoke(null,new object[]{root,name,hash,pins});throw new Exception("Drift accepted");}catch(TargetInvocationException e)when(e.InnerException is InvalidDataException){}}}finally{Directory.Delete(root,true);}Console.WriteLine("[S002HistoricalProducerPathControls] result=Passed source_and_package_drift=3");}
